// Value: protects=the session workbench derives attendance/result/lock tiles from the roster and hands the same marked/roster counts to the lock panel, so Khóa stays blocked until all are marked;
// fails_when=the page counts results for absent students, shows Sẵn sàng with an unmarked student, or stops passing markedCount/rosterCount so the lock button enables early;
// why_new=SessionLockActions is tested with hand-fed counts and the page only via a source regex; nothing rendered SessionDetailPage's tiles or its wiring;
// seam=none; no_claim=does not prove the server rejects an incomplete lock (lockSessionAction is mocked) or the tile colours
import { cleanup, render, screen } from "@testing-library/react";
import { afterEach, describe, expect, it, vi } from "vitest";

import type { SessionDetailReadModel, SessionParticipantReadModel } from "@/features/sessions/detail-read-models";

vi.mock("next/navigation", () => ({ useRouter: () => ({ push: vi.fn(), refresh: vi.fn() }) }));
vi.mock("@/features/sessions/actions/session-attendance-actions", () => ({ markSessionAttendanceAction: vi.fn(), updateSessionAttendanceAction: vi.fn() }));
vi.mock("@/features/sessions/actions/session-result-actions", () => ({ lockSessionAction: vi.fn(), recordSessionResultAction: vi.fn(), updateSessionResultAction: vi.fn() }));
vi.mock("@/features/sessions/actions/session-lifecycle-actions", () => ({ cancelSessionAction: vi.fn(), completeSessionAction: vi.fn(), rescheduleSessionAction: vi.fn(), startSessionAction: vi.fn() }));

import { SessionDetailPage } from "@/features/sessions/session-detail-page";

afterEach(cleanup);

const participant: SessionParticipantReadModel = {
  actualLearningMode: "offline", attendanceId: null, attendanceNotes: null, attendanceStatus: null, currentGrade: 7, enrollmentClassId: "class-1", enrollmentId: "enrollment-1", isLateUpdate: false, notebookScore: null, notebookStatus: null, registeredMode: "offline", resultComment: null, resultId: null, studentCode: "HV-001", studentId: "student-1", studentName: "Nguyễn Minh An", testScore: null,
};

function buildDetail(participants: SessionParticipantReadModel[]): SessionDetailReadModel {
  return {
    attendanceCount: null, cancellationReason: null, cancelledAt: null, classCode: "7A", classId: "class-1", className: "Toán 7A", classStatus: "active", completedAt: "2026-10-12T13:00:00Z", componentCode: null, endTime: "21:00:00", grade: 7, id: "session-1", learningMode: "offline", level: "A", lockedAt: null, lockReason: null, meetingUrl: null, notes: null, participants, previousSessionDate: null, rescheduleCount: 0, resultCount: null, roomName: "P. 101", rosterCount: null, sessionDate: "2026-10-12", sessionKind: "regular", startedAt: "2026-10-12T11:30:00Z", startTime: "18:30:00", status: "completed",
  };
}

const permissions = {
  additionalStudyCandidates: [],
  canLockSession: true,
  canManageResults: true,
  canManageSessions: false,
  canMarkAttendance: true,
  canViewAttendance: true,
  canViewResults: true,
  canViewStudents: true,
};

/** A workbench tile reads "<value> · <hint>"; the value and the hint are separate text nodes. */
function expectTile(value: string, hint?: string) {
  expect(screen.getByText(value)).toBeInTheDocument();
  if (hint) expect(screen.getByText(`· ${hint}`)).toBeInTheDocument();
}

describe("Session workbench tiles and lock wiring (design 04)", () => {
  it("blocks the lock while a roster member is unmarked and turns ready once everyone is marked", () => {
    const view = render(
      <SessionDetailPage
        {...permissions}
        detail={buildDetail([
          { ...participant, attendanceId: "att-a", attendanceStatus: "present", resultId: "res-a", studentId: "a", studentName: "An", testScore: 8 },
          { ...participant, attendanceId: "att-b", attendanceStatus: "additional_study", enrollmentClassId: null, enrollmentId: null, studentId: "b", studentName: "Bình" },
          { ...participant, attendanceId: "att-c", attendanceStatus: "excused_absence", studentId: "c", studentName: "Cúc" },
          { ...participant, studentId: "d", studentName: "Dũng" },
        ])}
      />,
    );

    expectTile("3/4", "1 chưa điểm danh");
    // Absent students are not eligible for results: 1 of 2 (present + additional study).
    expectTile("1/2", "thiếu 1");
    expectTile("Bị chặn · thiếu 1 điểm danh");
    expect(screen.getByRole("button", { name: "Khóa buổi học" })).toBeDisabled();
    // The walk-in (Bình) is not on the roster, so the lock checklist counts 3 roster students.
    expect(screen.getByText(/thiếu 1\/3/)).toBeInTheDocument();

    view.rerender(
      <SessionDetailPage
        {...permissions}
        detail={buildDetail([
          { ...participant, attendanceId: "att-a", attendanceStatus: "present", resultId: "res-a", studentId: "a", studentName: "An", testScore: 8 },
          { ...participant, attendanceId: "att-b", attendanceStatus: "additional_study", enrollmentClassId: null, enrollmentId: null, resultId: "res-b", studentId: "b", studentName: "Bình" },
          { ...participant, attendanceId: "att-c", attendanceStatus: "excused_absence", studentId: "c", studentName: "Cúc" },
          { ...participant, attendanceId: "att-d", attendanceStatus: "unexcused_absence", studentId: "d", studentName: "Dũng" },
        ])}
      />,
    );

    expectTile("4/4", "đủ roster");
    expectTile("2/2", "đủ cho học sinh có mặt");
    expectTile("Sẵn sàng");
    expect(screen.queryByText(/Bị chặn/)).not.toBeInTheDocument();
    expect(screen.getByRole("button", { name: "Khóa buổi học" })).toBeEnabled();
    expect(screen.getByText("Điểm danh đủ 3/3 học sinh")).toBeInTheDocument();
  });

  // Value: protects=lock readiness mirrors lock_class_session_internal (roster students only; present/excused/unexcused only);
  // fails_when=a roster student marked additional_study counts as ready, or a walk-in counts against readiness;
  // why_new=review finding: the page counted any non-null status across all participants, so Khóa enabled and the server rejected;
  // seam=none; no_claim=does not prove the server's enrollment-id join (attendance under a different enrollment)
  it("keeps the lock blocked while a roster student is only marked additional_study", () => {
    render(
      <SessionDetailPage
        {...permissions}
        detail={buildDetail([
          { ...participant, attendanceId: "att-a", attendanceStatus: "present", studentId: "a", studentName: "An" },
          { ...participant, attendanceId: "att-b", attendanceStatus: "additional_study", studentId: "b", studentName: "Bình" },
          { ...participant, attendanceId: "att-w", attendanceStatus: "additional_study", enrollmentClassId: null, enrollmentId: null, studentId: "w", studentName: "Vãng lai" },
        ])}
      />,
    );

    // Display tile still reports everyone on the page as marked…
    expectTile("3/3", "đủ roster");
    // …but the lock needs present or an absence for each roster student; the walk-in is not counted.
    expectTile("Bị chặn · thiếu 1 điểm danh");
    expect(screen.getByText(/thiếu 1\/2/)).toBeInTheDocument();
    expect(screen.getByRole("button", { name: "Khóa buổi học" })).toBeDisabled();
  });
});
